'use strict';
// Matchday extension. The possession engine is authoritative; animation illustrates its resolved play.
const originalRender=render,originalAdvance=advance,originalSimulate=simulate,originalNextSeason=nextSeason,originalStartCareer=startCareer,originalGo=go;
let autoTimer=null,animationTimer=null,animating=false,autoSpeed=1500,liveTab='feed',coachTab='profile';
const offenses=['Shotgun spread','Singleback','I formation','Empty backfield'];
const defenses=['4–3 base','3–4 base','Nickel','Dime'];
const offCalls=[['Inside run','Steady gain · low risk'],['Outside run','Attack the edge'],['Quick pass','Short routes · reliable'],['Deep pass','Vertical shot · high risk'],['Play action','Sell the run · throw deep'],['Screen','Counter the blitz'],['Punt','Trade possession for field position'],['Field goal','Attempt three points']];
const defCalls=[['Cover 2','Limit explosive passes'],['Man coverage','Challenge receivers'],['Zone blitz','Pressure with cover'],['All-out blitz','High pressure · high risk'],['Run contain','Protect the edges'],['Prevent','Deep coverage · allows short gains']];
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function ensureMatchState(){state.coach??={name:'Alex Morgan',style:'Balanced',offense:'Shotgun spread',defense:'Nickel',calling:'Manual',temperament:'Players coach'};state.press??=[];state.mediaTrust??=65;state.live??=null;state.lastMatch??=null;state.interviewPending??=null;state.roster.forEach(p=>{p.fitness??=100});if(!state.matchUpgrade){state.matchUpgrade=true;['LB','CB','S','K'].forEach((pos,i)=>{if(!state.roster.some(p=>p.pos===pos&&!p.starter)&&state.roster.length<53&&money()+1.5<=255){let p=player(450+i);state.roster.push({...p,id:'depth-'+state.year+'-'+pos,pos,ovr:68+i,pot:78+i,salary:1.5,starter:false,fitness:100})}})}}
function logo(i,cls=''){let code=clubs[i][0].toLowerCase();if(code==='was')code='wsh';return `<img class="team-logo ${cls}" src="logos/${code}.png" alt="${cname(i)} logo" onerror="this.style.display='none';this.insertAdjacentText('afterend','${clubs[i][0]}')">`}
navs.push(['Matchday','▷'],['Head coach','♟'],['Media room','◌']);
function customNav(active){document.getElementById('nav').innerHTML=navs.map(([n,i])=>`<button class="${active===n?'active':''}" onclick="go('${n}')"><span>${i}</span>${n}${n==='Matchday'&&state.live?'<sup class="new-tag">LIVE</sup>':''}</button>`).join('')}
function decorate(){document.querySelectorAll('.crest,.shield').forEach(el=>{const i=clubs.findIndex(c=>c[0]===el.textContent.trim());if(i>=0){el.classList.add('logo-crest');el.innerHTML=logo(i)}});let footer=document.querySelector('footer span');if(footer)footer.innerHTML='Unlicensed fan simulation · Fictional personnel · <a href="#" onclick="showLicensing();return false">Branding & credits ↗</a>'}
render=function(){ensureMatchState();let actual=view,special=['Matchday','Head coach','Media room'].includes(actual);if(special)view='Overview';originalRender();view=actual;customNav(actual);if(special){let titles={Matchday:['THE SIDELINE','Every snap is a decision.'], 'Head coach':['THE HEADSET','Define the person behind the playbook.'],'Media room':['BEHIND THE MICROPHONE','Your words travel beyond the locker room.']};document.getElementById('breadcrumb').textContent='FRONT OFFICE / '+actual.toUpperCase();document.getElementById('app').innerHTML=`<div class="title-row"><div><div class="eyebrow">${state.year} SEASON · ${phaseName()}</div><h1>${titles[actual][0]}</h1><p class="subtitle">${titles[actual][1]}</p></div><span class="tag green">${state.live?'MATCH IN PROGRESS':actual==='Matchday'?'MATCHDAY CENTER':'FRANCHISE OPERATIONS'}</span></div>${actual==='Matchday'?matchScreen():actual==='Head coach'?coachScreen():mediaScreen()}`};decorate();save()};
go=function(v){if(v!=='Matchday')pauseAuto();originalGo(v)};
actionLabel=function(){return state.live?'Return to live game →':state.phase==='offseason'?'Begin next season →':game()?'Enter matchday →':'Simulate playoff round →'};
advance=function(){ensureMatchState();if(state.live){view='Matchday';render();return}if(state.interviewPending){postInterview();return}if(state.phase==='offseason'||!game()){originalAdvance();return}pregame()};
function pregame(){pauseAuto();modal(`<div class="eyebrow">MATCHDAY · ${phaseName()}</div><div class="score-summary" style="margin:20px 0">${logo(state.team)}<b>${clubs[state.team][0]} vs ${clubs[opponent()][0]}</b>${logo(opponent())}</div><h2>The sideline is yours.</h2><p>Call each offensive and defensive snap, make substitutions between plays, or delegate to ${esc(state.coach.name)}. The game pauses for halftime and the final whistle.</p><div class="kv"><span>Offensive formation</span><b>${state.coach.offense}</b></div><div class="kv"><span>Defensive personnel</span><b>${state.coach.defense}</b></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Back</button><button onclick="beginLive()">Take the field →</button></div>`)}
function beginLive(){if(state.live){closeModal();go('Matchday');return}let g=game();if(!g)return;ensureMatchState();seed=Date.now()>>>0;state.roster.forEach(p=>p.fitness=Math.min(100,(p.fitness??100)+5));state.live={a:g.a,b:g.b,score:[0,0],quarter:1,clock:900,poss:0,spot:25,down:1,toGo:10,offense:state.coach.offense,defense:state.coach.defense,call:'Quick pass',defCall:'Cover 2',tempo:'Normal',events:[],plays:0,timeouts:[3,3],stopped:false,halftime:false,finished:false,stats:[{yards:0,pass:0,rush:0,first:0,turnovers:0,plays:0},{yards:0,pass:0,rush:0,first:0,turnovers:0,plays:0}],periodScores:[[0,0],[0,0],[0,0],[0,0]],last:null,interviewDone:false};addEvent('Kickoff. '+clubs[g.a][2]+' take possession at their own 25.',true);closeModal();view='Matchday';render();pregameInterview()}
function teamIndex(m=state.live){return m.a===state.team?0:1}function onOffense(m=state.live){return m.poss===teamIndex(m)}function clockText(m){return Math.floor(m.clock/60)+':'+String(m.clock%60).padStart(2,'0')}function possessionTeam(m){return m.poss===0?m.a:m.b}function fieldPosition(m){return m.spot===50?'MIDFIELD':m.spot<50?clubs[possessionTeam(m)][0]+' '+m.spot:clubs[m.poss===0?m.b:m.a][0]+' '+(100-m.spot)}
function addEvent(text,highlight=false){let m=state.live;if(!m)return;m.events.unshift({text,time:(m.quarter>4?'OT':'Q'+m.quarter)+' '+clockText(m),highlight});m.events=m.events.slice(0,200)}
function advice(m){if(m.halftime)return 'Halftime. Review your game plan, rotate tired players, and deliver your team talk.';if(m.finished)return 'Final whistle. Review the game and face the media before returning to the front office.';if(m.down===4)return m.spot>58?'Fourth down in scoring range. Consider a field goal, or keep the offense out if the situation demands it.':'Fourth down. A punt protects field position; going for it risks a short field.';if(m.clock<180&&m.quarter===4&&m.score[teamIndex(m)]<m.score[1-teamIndex(m)])return 'We are chasing the game. Use hurry-up and attack downfield; timeouts can reduce the next play’s clock runoff.';if(state.roster.some(p=>p.starter&&p.fitness<72))return 'Fatigue is affecting execution. Fresh reserves can provide a lift even with a lower overall rating.';return onOffense(m)?'Read the situation. Spread and empty formations favor passing; I formation helps the run. Every call changes risk and yardage.':'Nickel and dime protect the pass. Base fronts help against the run. Blitzing can force mistakes but exposes the secondary.'}
function matchScreen(){let m=state.live;if(!m)return `<div class="panel"><div class="pad"><div class="eyebrow">${state.phase==='offseason'?'OFFSEASON':'READY WHEN YOU ARE'}</div><h1 style="margin:16px 0">${game()?'The next game is waiting.':'No upcoming game.'}</h1><p class="subtitle">${game()?'Take the headset. Choose your formations and call every snap.':'Advance the calendar from your front office.'}</p><button style="margin-top:24px" onclick="advance()">${actionLabel()}</button></div></div>${state.lastMatch?postgameCard(state.lastMatch):''}`;let mine=teamIndex(m),off=onOffense(m);return `<div class="live-layout"><div><div class="panel"><div class="scoreboard"><div class="score-team">${logo(m.a)}<div><b>${clubs[m.a][0]}</b><small>HOME ${m.a===state.team?'· YOU':''}</small></div><strong>${m.score[0]}</strong></div><div class="score-time">${m.finished?'FINAL':m.halftime?'HALFTIME':clockText(m)}<small>${m.quarter>4?'OVERTIME':'QUARTER '+m.quarter} · ${autoTimer?'LIVE':'PAUSED'}</small></div><div class="score-team"><strong>${m.score[1]}</strong><div><b>${clubs[m.b][0]}</b><small>AWAY ${m.b===state.team?'· YOU':''}</small></div>${logo(m.b)}</div></div><div class="match-banner"><b>${off?'YOUR OFFENSE':'YOUR DEFENSE'} · ${m.down}${['st','nd','rd','th'][m.down-1]} & ${m.toGo} · ${fieldPosition(m)}</b><span>TIMEOUTS ${'●'.repeat(m.timeouts[mine])}${'○'.repeat(3-m.timeouts[mine])}</span></div>${liveField(m)}<div class="match-controls"><button onclick="snap()" ${animating||m.halftime||m.finished?'disabled':''}>${animating?'Play in motion…':'▶ Snap ball'}</button><button class="secondary" onclick="toggleAuto()" ${m.halftime||m.finished?'disabled':''}>${autoTimer?'Ⅱ Pause':'▷ Auto play'}</button><select aria-label="Simulation speed" onchange="setSpeed(this.value)"><option value="2500" ${autoSpeed===2500?'selected':''}>Slow</option><option value="1500" ${autoSpeed===1500?'selected':''}>Normal</option><option value="750" ${autoSpeed===750?'selected':''}>Fast</option></select><button class="secondary" onclick="timeout()" ${animating||m.halftime||m.finished||!m.timeouts[mine]?'disabled':''}>Timeout (${m.timeouts[mine]})</button><button class="secondary" onclick="showSubs()" ${animating||m.finished?'disabled':''}>Substitutions ⇄</button>${m.halftime?'<button onclick="halftimeTalk()">Halftime team talk →</button>':''}${m.finished?'<button onclick="commitMatch()">Postgame report →</button>':''}</div><div style="padding:0 17px;color:var(--muted);font-size:10px">● Light jerseys: offense &nbsp; ● Coral jerseys: defense &nbsp; | Blue: scrimmage &nbsp; | Yellow: first down</div><div class="advisor"><b>${esc(state.coach.name)} · SIDELINE NOTE</b><br>${advice(m)}</div></div><div class="two section-gap"><div class="panel"><div class="panel-head"><h2>Play-by-play</h2><span class="label">${m.plays} SNAPS</span></div><div class="play-feed" aria-live="polite">${m.events.slice(0,30).map(e=>`<div class="play-event ${e.highlight?'highlight':''}"><time>${e.time}</time><span>${esc(e.text)}</span></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><h2>Live statistics</h2><span class="label">${clubs[m.a][0]} / ${clubs[m.b][0]}</span></div><div class="pad">${[['yards','Total yards'],['pass','Passing yards'],['rush','Rushing yards'],['first','First downs'],['turnovers','Turnovers'],['plays','Plays']].map(([k,l])=>`<div class="stat-pair"><b>${m.stats[0][k]}</b><span>${l}</span><b>${m.stats[1][k]}</b></div>`).join('')}</div></div></div></div><div class="match-sidebar"><div class="panel match-panel"><div class="panel-head"><h2>The play sheet</h2><span class="tag green">${off?'OFFENSE':'DEFENSE'}</span></div><div class="pad"><div class="form-row"><label for="formation">${off?'Offensive formation':'Defensive personnel'}</label><select id="formation" ${animating?'disabled':''} onchange="matchSetting('${off?'offense':'defense'}',this.value)">${(off?offenses:defenses).map(o=>`<option ${m[off?'offense':'defense']===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="play-grid">${(off?offCalls:defCalls).map(([c,d])=>`<button class="play-card ${m[off?'call':'defCall']===c?'selected':''}" ${animating||m.finished?'disabled':''} onclick="matchSetting('${off?'call':'defCall'}','${c}')">${c}<small>${d}</small></button>`).join('')}</div><div class="form-row" style="margin-top:18px"><label for="tempo">Tempo</label><select id="tempo" onchange="matchSetting('tempo',this.value)" ${animating?'disabled':''}>${['Normal','Hurry-up','Chew clock'].map(o=>`<option ${m.tempo===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="form-row"><label for="caller">Playcaller</label><select id="caller" onchange="changeCaller(this.value)"><option ${state.coach.calling==='Manual'?'selected':''}>Manual</option><option ${state.coach.calling==='Head coach'?'selected':''}>Head coach</option></select><small>Manual repeats your selected call during auto play. Head coach chooses situational calls.</small></div></div></div><div class="panel section-gap"><div class="panel-head"><h2>Personnel readiness</h2><button class="link" onclick="showSubs()" ${animating||m.finished?'disabled':''}>Manage ↗</button></div><div class="pad">${state.roster.filter(p=>p.starter&&['QB','RB','WR','LB','CB'].includes(p.pos)).slice(0,7).map(p=>`<div class="kv"><span>${p.pos} · ${p.name.split(' ').at(-1)}</span><b>${p.injury?'<span class="negative">OUT</span>':Math.round(p.fitness)+'%'}</b></div>`).join('')}</div></div></div></div><p class="subtitle">2D schematic simulation. Four 15-minute quarters; simplified clock, special teams and sudden-death overtime. No penalties or challenges.</p>`}
function xCoord(spot,poss){return 8.333+(poss===0?spot:100-spot)*.83334}
function liveField(m){let x=xCoord(m.spot,m.poss),dir=m.poss===0?1:-1;let spread=m.offense==='Empty backfield'?1.25:m.offense==='I formation'?.65:1;let offensePoints=[[-3,50,'QB'],[-5,62,'RB'],[-1,13,'WR'],[-1,87,'WR'],[-1,74,'TE'],[0,40,'OL'],[0,45,'OL'],[0,50,'C'],[0,55,'OL'],[0,60,'OL'],[-2,25,'WR']];let defensePoints=[[2,40,'D'],[2,46,'D'],[2,54,'D'],[2,60,'D'],[5,30,'LB'],[5,50,'LB'],[5,70,'LB'],[4,12,'CB'],[4,88,'CB'],[10,38,'S'],[10,65,'S']];if(m.defense==='3–4 base'){defensePoints[3]=[5,61,'LB'];defensePoints[6]=[5,77,'LB']}if(m.defense==='Nickel'){defensePoints[6]=[7,76,'CB']}if(m.defense==='Dime'){defensePoints[4]=[9,25,'CB'];defensePoints[6]=[9,76,'CB']}if(m.offense==='I formation'){offensePoints[0]=[-2,50,'QB'];offensePoints[1]=[-7,50,'RB'];offensePoints[10]=[-5,50,'FB']}if(m.offense==='Singleback'){offensePoints[1]=[-7,50,'RB']}let receiverFormation=m.offense==='Empty backfield';return `<div class="live-field" id="live-pitch"><div class="endzone"><span>${clubs[m.a][0]}</span></div><div class="endzone right"><span>${clubs[m.b][0]}</span></div><div class="pitch-center">${logo(state.team)}</div>${Array.from({length:11},(_,i)=>`<div class="yard-line" style="left:${8.333+i*8.333}%"><span>${i===0||i===10?'':i<=5?i*10:100-i*10}</span></div>`).join('')}<div class="line-scrimmage" style="left:${x}%"></div><div class="line-first" style="left:${xCoord(Math.min(100,m.spot+m.toGo),m.poss)}%"></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" style="position:absolute;width:100%;height:100%"><path class="route-line" d="M ${x-dir} 13 L ${Math.max(4,Math.min(96,x+dir*12))} 13 L ${Math.max(4,Math.min(96,x+dir*18))} 30"/></svg>${offensePoints.map(([dx,y,p],i)=>{if(receiverFormation&&p==='RB'){dx=-1;y=8}return `<i class="athlete" id="o${i}" style="left:${Math.max(2,Math.min(98,x+dx*dir))}%;top:${Math.max(6,Math.min(94,50+(y-50)*spread))}%">${p}</i>`}).join('')}${defensePoints.map(([dx,y,p],i)=>`<i class="athlete defender" id="d${i}" style="left:${Math.max(2,Math.min(98,x+dx*dir))}%;top:${y}%">${p}</i>`).join('')}<i class="ball-dot" id="ball" style="left:${x-3*dir}%;top:50%"></i><div class="play-overlay">${m.last?esc(m.last.text):'Set your formation. Call your play. Own the moment.'}</div></div>`}
function matchSetting(k,v){if(animating||!state.live)return;state.live[k]=v;render()}
function changeCaller(v){state.coach.calling=v;save()}
function setSpeed(v){autoSpeed=Number(v);if(autoTimer){pauseAuto();startAuto()}}
function pauseAuto(){if(autoTimer){clearInterval(autoTimer);autoTimer=null}}
function startAuto(){if(!state.live||state.live.finished||state.live.halftime)return;autoTimer=setInterval(()=>{if(!animating)snap()},autoSpeed);render()}
function toggleAuto(){if(autoTimer){pauseAuto();render()}else startAuto()}
function timeout(){let m=state.live;if(!m||animating||m.finished||m.halftime)return;let k=teamIndex(m);if(!m.timeouts[k])return;pauseAuto();m.timeouts[k]--;m.stopped=true;addEvent(clubs[state.team][2]+' call timeout. Next snap has minimal clock runoff.',true);render()}
function unitRating(pos){let ps=state.roster.filter(p=>p.starter&&pos.includes(p.pos));return ps.reduce((s,p)=>s+(p.ovr-(p.injury?25:0))*(.65+.35*p.fitness/100),0)/Math.max(1,ps.length)}
function coachCall(m){if(m.down===4)return m.spot>=60?'Field goal':(m.quarter===4&&m.score[m.poss]<m.score[1-m.poss]&&m.clock<240?'Deep pass':'Punt');if(m.toGo<=2)return 'Inside run';if(state.coach.style==='Run-first')return rand()<.65?'Inside run':'Play action';if(state.coach.style==='Vertical offense')return rand()<.55?'Deep pass':'Quick pass';if(m.toGo>8)return rand()<.6?'Quick pass':'Deep pass';return rand()<.45?'Inside run':'Quick pass'}
function flip(m,newSpot){m.poss=1-m.poss;m.spot=Math.max(1,Math.min(99,newSpot));m.down=1;m.toGo=Math.min(10,100-m.spot)}
function addScore(m,k,points){m.score[k]+=points;m.periodScores[m.quarter-1]??=[0,0];m.periodScores[m.quarter-1][k]+=points}
function resolveSnap(){let m=state.live;if(!m||m.finished||m.halftime)return;let own=onOffense(m),k=m.poss,team=possessionTeam(m),start=m.spot,passing,turnover=false,yards=0,highlight=false;let call=own?(state.coach.calling==='Head coach'?coachCall(m):m.call):coachCall({...m,call:'Quick pass'});if(own&&state.coach.calling==='Head coach')m.call=call;let defense=own?(['Cover 2','Man coverage','Run contain','Zone blitz'][ri(0,3)]):m.defCall;if(!own&&state.coach.calling==='Head coach'){defense=m.toGo>7?'Cover 2':'Run contain';m.defCall=defense}let atk=own?unitRating(['QB','WR','RB','OL']):state.teams[team].rating,def=own?state.teams[m.b===team?m.a:m.b].rating:unitRating(['DL','LB','CB','S']);let edge=(atk-def)/22+(own?(state.morale-70)/70:0);if(state.coach.temperament==='Disciplinarian'&&state.morale>=70)edge+=own?.18:-.18;if(own&&state.coach.temperament==='Tactician'&&((['Deep pass','Quick pass','Screen'].includes(call)&&['Shotgun spread','Empty backfield'].includes(m.offense))||(['Inside run','Outside run'].includes(call)&&m.offense==='I formation')))edge+=.3;let formation=own?m.offense:offenses[ri(0,3)],df=own?defenses[ri(0,3)]:m.defense;let label=clubs[team][0],text='',dead=false;passing=!['Inside run','Outside run','Punt','Field goal'].includes(call);let period=m.quarter,atClock=clockText(m);m.stats[k].plays++;m.plays++;
if(call==='Punt'){let distance=Math.min(99-m.spot,ri(35,53));let landing=m.spot+distance;flip(m,landing>=95?20:100-landing);text=label+' punt '+distance+' yards. Possession changes.';dead=true}
else if(call==='Field goal'){let distance=117-m.spot,kick=own?unitRating(['K']):78,chance=Math.max(.02,Math.min(.98,1.08-(distance-25)*.018+(kick-75)*.004));if(rand()<chance){addScore(m,k,3);flip(m,25);text=label+' make a '+distance+'-yard field goal!';highlight=true}else{flip(m,Math.max(20,100-start+7));text=label+' miss a '+distance+'-yard field goal.'}dead=true}
else {let blitz=defense.includes('blitz'),runHelp=(formation==='I formation'?1.8:formation==='Singleback'?.8:formation==='Empty backfield'?-2:0);let frontRun=df==='4–3 base'||df==='3–4 base'?-1.1:df==='Dime'?1.8:.4;
if(passing){let deep=call==='Deep pass'||call==='Play action';let complete=.67+edge*.045+(formation==='Shotgun spread'||formation==='Empty backfield'?.05:0)-(deep?.19:0)+(call==='Screen'&&blitz?.13:0)-(df==='Dime'?.07:df==='Nickel'?.035:0)-(defense==='Prevent'&&deep?.13:0);if(rand()<.035+(blitz?.065:0)-edge*.006){yards=-ri(3,10);text=label+' '+call+': quarterback sacked for '+Math.abs(yards)+' yards.'}else if(rand()<.018+(deep?.025:0)+(blitz?.012:0)){turnover=true;text=label+' '+call+': INTERCEPTED!';highlight=true}else if(rand()>complete){text=label+' '+call+': incomplete.';dead=true}else{yards=Math.max(1,Math.round((deep?ri(10,34):call==='Screen'?ri(0,15):ri(2,13))+edge+(defense==='Prevent'&&!deep?3:0)));if(rand()<.04)yards+=ri(15,30);text=label+' '+call+': complete for '+Math.min(yards,100-start)+' yards.'}}
else{yards=Math.round(ri(-3,10)+edge+runHelp+frontRun+(defense==='Run contain'?-2:0)+(call==='Outside run'?ri(-2,3):0));if(rand()<.06)yards+=ri(10,25);if(rand()<.014){turnover=true;text=label+' '+call+': fumble recovered by the defense!';highlight=true}else text=label+' '+call+': '+Math.min(yards,100-start)+' yards.'}
if(turnover){m.stats[k].turnovers++;flip(m,100-start)}else{yards=Math.min(yards,100-start);m.stats[k].yards+=yards;m.stats[k][passing?'pass':'rush']+=yards;m.spot+=yards;if(m.spot>=100){addScore(m,k,7);flip(m,25);text+=' TOUCHDOWN! Extra point good.';highlight=true}else if(m.spot<=0){addScore(m,1-k,2);flip(m,35);text+=' SAFETY!';highlight=true}else if(yards>=m.toGo){m.down=1;m.toGo=Math.min(10,100-m.spot);m.stats[k].first++;text+=' First down.'}else{m.down++;m.toGo-=yards;if(m.down>4){flip(m,100-m.spot);text+=' Turnover on downs.';highlight=true}}}}
let elapsed=m.stopped?ri(4,9):dead?ri(5,12):own&&m.tempo==='Hurry-up'?ri(12,22):own&&m.tempo==='Chew clock'?ri(38,44):ri(25,39);m.stopped=false;m.clock=Math.max(0,m.clock-elapsed);state.roster.forEach(p=>{if(p.starter&&!p.injury)p.fitness=Math.max(45,p.fitness-(own===['QB','RB','WR','TE','OL'].includes(p.pos)?.75:.15)*(state.coach.temperament==='Players coach'?.9:1));else p.fitness=Math.min(100,p.fitness+.65)});if(rand()<.006){let available=state.roster.filter(p=>p.starter&&!p.injury),p=available[ri(0,available.length-1)];if(p){p.injury=ri(1,2);text+=' '+p.name+' is injured — check substitutions.';highlight=true;pauseAuto()}}m.last={text,start,spot:turnover?start:Math.max(0,Math.min(100,start+yards)),poss:k,passing,call};m.events.unshift({text,time:(period>4?'OT':'Q'+period)+' '+atClock,highlight});m.events=m.events.slice(0,200);
if(m.quarter>4&&(m.score[0]!==m.score[1])){m.finished=true;pauseAuto()}
if(!m.clock&&!m.finished){if(m.quarter===2){m.halftime=true;pauseAuto();addEvent('Halftime. Meet the team in the locker room.',true)}else if(m.quarter>=4){if(m.score[0]!==m.score[1]){m.finished=true;pauseAuto()}else{m.quarter++;m.clock=600;m.periodScores.push([0,0]);flip(m,25);addEvent('Sudden-death overtime. Next score wins.',true)}}else{m.quarter++;m.clock=900;addEvent('Start of quarter '+m.quarter+'.',true)}}return m.last}
function animatePlay(last){if(!last)return;let dir=last.poss===0?1:-1,x=xCoord(last.spot,last.poss);for(let i=0;i<11;i++){let o=document.getElementById('o'+i),d=document.getElementById('d'+i);if(o){o.style.left=Math.max(2,Math.min(98,x+(i<5?(i-2)*1.3:-3)*dir))+'%';o.style.top=(i<5?22+i*12:36+(i-5)*5)+'%'}if(d){d.style.left=Math.max(2,Math.min(98,x+(i-4)*dir*.7))+'%';d.style.top=(25+i*5)+'%'}}let ball=document.getElementById('ball');if(ball){ball.style.left=x+'%';ball.style.top=last.passing?'35%':'58%'}}
function snap(){let m=state.live;if(!m||m.finished||m.halftime||animating)return;animating=true;render();let last=resolveSnap();save();animatePlay(last);animationTimer=setTimeout(()=>{animationTimer=null;animating=false;if(view==='Matchday')render()},Math.min(900,autoSpeed-100))}
function halftimeTalk(){let m=state.live;if(!m||!m.halftime)return;pauseAuto();modal(`<div class="eyebrow">HALFTIME · LOCKER ROOM</div><h2>Make the next 30 minutes count.</h2><p>${clubs[m.a][0]} ${m.score[0]} – ${m.score[1]} ${clubs[m.b][0]}. Your starters recover energy at the break. What is your message?</p><button class="interview-option" onclick="resumeHalf('Encourage')">“Trust your preparation. We have another gear.”<small>Encourage · morale +3</small></button><button class="interview-option" onclick="resumeHalf('Demand more')">“Raise the standard. Every detail matters.”<small>Demand more · +4 morale when trailing; −2 when ahead</small></button><button class="interview-option" onclick="resumeHalf('Stay composed')">“Stay disciplined and execute the plan.”<small>Composure · morale +1, extra fitness recovery</small></button>`)}
function resumeHalf(choice){let m=state.live;if(!m||!m.halftime)return;let k=teamIndex(m);state.morale=Math.max(35,Math.min(99,state.morale+(choice==='Encourage'?3:choice==='Demand more'?(m.score[k]<m.score[1-k]?4:-2):1)));state.roster.forEach(p=>p.fitness=Math.min(100,p.fitness+(choice==='Stay composed'?15:10)));m.halftime=false;m.quarter=3;m.clock=900;m.poss=1;m.spot=25;m.down=1;m.toGo=10;m.timeouts=[3,3];addEvent('Second-half kickoff. '+clubs[m.b][2]+' receive.',true);closeModal();render()}
function showSubs(){if(animating||!state.live||state.live.finished)return;pauseAuto();modal(`<h2>Sideline substitutions</h2><p>Replace a starter with a healthy reserve at the same position. Changes apply on the next snap; fitness influences execution.</p><div class="scroll" style="max-height:440px"><table><thead><tr><th>ON THE FIELD</th><th>CONDITION</th><th>REPLACEMENT</th></tr></thead><tbody>${state.roster.filter(p=>p.starter).map(p=>`<tr><td>${p.pos} · ${p.name}<small>OVR ${p.ovr}${p.injury?' · INJURED':''}</small></td><td>${Math.round(p.fitness)}%</td><td><select aria-label="Replace ${p.name}" onchange="subPlayer('${p.id}',this.value)"><option value="">Choose reserve</option>${state.roster.filter(q=>!q.starter&&q.pos===p.pos&&!q.injury).map(q=>`<option value="${q.id}">${q.name} · ${q.ovr} OVR · ${Math.round(q.fitness)}%</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button onclick="closeModal();render()">Back to sideline</button></div>`)}
function subPlayer(outId,inId){if(!inId||animating||!state.live||state.live.finished)return;let out=state.roster.find(p=>p.id===outId),inside=state.roster.find(p=>p.id===inId);if(!out?.starter||!inside||inside.starter||inside.injury||inside.pos!==out.pos)return;out.starter=false;inside.starter=true;addEvent('Substitution: '+inside.name+' replaces '+out.name+' at '+out.pos+'.',true);save();showSubs()}
simulate=function(g,regular){if(state.pendingLiveScore&&g.a===state.pendingLiveScore.a&&g.b===state.pendingLiveScore.b){g.score=[...state.pendingLiveScore.score];if(regular)[g.a,g.b].forEach((i,k)=>{let t=state.teams[i];t.pf+=g.score[k];t.pa+=g.score[1-k];t[g.score[k]>g.score[1-k]?'w':'l']++});return g.score[0]>g.score[1]?g.a:g.b}return originalSimulate(g,regular)};
function commitMatch(){let m=state.live;if(!m?.finished||animating)return;pauseAuto();state.lastMatch=JSON.parse(JSON.stringify(m));state.pendingLiveScore={a:m.a,b:m.b,score:[...m.score]};state.live=null;view='Overview';originalAdvance();delete state.pendingLiveScore;state.interviewPending={type:'post',year:state.year,week:state.week};render();closeModal();postgameReport()}
function postgameCard(m){return `<div class="panel section-gap"><div class="panel-head"><h2>Last game · Final</h2><button class="link" onclick="postgameReport()">Full report ↗</button></div><div class="pad"><div class="score-summary">${logo(m.a)}<b>${clubs[m.a][0]}</b><span class="mini-result">${m.score[0]} – ${m.score[1]}</span><b>${clubs[m.b][0]}</b>${logo(m.b)}</div></div></div>`}
function postgameReport(){let m=state.lastMatch;if(!m)return;modal(`<div class="eyebrow">POSTGAME ANALYSIS · FINAL</div><div class="score-summary">${logo(m.a)}<div class="mini-result">${m.score[0]} – ${m.score[1]}</div>${logo(m.b)}</div><div class="scroll"><table><thead><tr><th>TEAM</th>${m.periodScores.map((_,i)=>`<th>${i<4?'Q'+(i+1):'OT'+(i-3)}</th>`).join('')}<th>FINAL</th></tr></thead><tbody>${[0,1].map(k=>`<tr><td>${clubs[k===0?m.a:m.b][0]}</td>${m.periodScores.map(q=>`<td>${q[k]}</td>`).join('')}<td>${m.score[k]}</td></tr>`).join('')}</tbody></table></div>${[['yards','Total yards'],['first','First downs'],['turnovers','Turnovers']].map(([k,l])=>`<div class="stat-pair"><b>${m.stats[0][k]}</b><span>${l}</span><b>${m.stats[1][k]}</b></div>`).join('')}<p style="margin-top:16px">${m.plays} plays. ${m.events.filter(e=>e.highlight).slice(0,2).map(e=>esc(e.text)).join(' ')}</p><div class="modal-actions"><button class="secondary" onclick="closeModal()">Close report</button>${state.interviewPending?'<button onclick="postInterview()">Attend press conference →</button>':'<button onclick="closeModal();go(\'Media room\')">Media room →</button>'}</div>`)}
function pregameInterview(){modal(`<div class="press-backdrop">${logo(state.team)}<div><div class="eyebrow">PREGAME INTERVIEW</div><h2 style="margin:6px 0 0">Set the tone.</h2></div></div><p>“Coach ${esc(state.coach.name)}, what should fans expect from your team today?”</p><button class="interview-option" onclick="answerInterview('pre',0)">“We trust our preparation and each other.”<small>Measured confidence · morale +2</small></button><button class="interview-option" onclick="answerInterview('pre',1)">“We’re here to make a statement.”<small>Bold promise · morale +4, media trust −2</small></button><button class="interview-option" onclick="answerInterview('pre',2)">“We’ll let our performance do the talking.”<small>Stay private · no morale change</small></button>`)}
function postInterview(){if(!state.interviewPending)return;let m=state.lastMatch,k=teamIndex(m),win=m.score[k]>m.score[1-k];modal(`<div class="press-backdrop">${logo(state.team)}<div><div class="eyebrow">POSTGAME PRESS CONFERENCE</div><h2 style="margin:6px 0 0">Face the questions.</h2></div></div><p>“Coach, ${win?'what made the difference in today’s win?':'where did things get away from your team today?'}”</p><button class="interview-option" onclick="answerInterview('post',0)">“${win?'The players earned this. They executed together.':'That starts with me. We will learn and improve.'}”<small>Support the locker room · morale +3, media trust +2</small></button><button class="interview-option" onclick="answerInterview('post',1)">“We have to be sharper. Our standard is higher.”<small>Demand improvement · morale −2, media trust +1</small></button><button class="interview-option" onclick="answerInterview('post',2)">“We’ll review the film before drawing conclusions.”<small>Measured response · media trust +1</small></button>`)}
function answerInterview(type,choice){ensureMatchState();if(type==='pre'){if(!state.live||state.live.interviewDone)return;state.live.interviewDone=true}else if(!state.interviewPending)return;let delta=type==='pre'?[2,4,0][choice]:[3,-2,0][choice],trust=type==='pre'?[1,-2,0][choice]:[2,1,1][choice];state.morale=Math.max(35,Math.min(99,state.morale+delta));state.mediaTrust=Math.max(0,Math.min(100,state.mediaTrust+trust));let quote=type==='pre'?['We trust our preparation and each other.','We’re here to make a statement.','We’ll let our performance do the talking.'][choice]:[(state.lastMatch.score[teamIndex(state.lastMatch)]>state.lastMatch.score[1-teamIndex(state.lastMatch)]?'The players earned this. They executed together.':'That starts with me. We will learn and improve.'),'We have to be sharper. Our standard is higher.','We’ll review the film before drawing conclusions.'][choice];state.press.unshift({type,quote,coach:state.coach.name,year:state.year,week:state.week,morale:delta,trust});if(type==='post')state.interviewPending=null;news(type==='pre'?'Coach sets the tone':'From the press room',quote);closeModal();render();toast('Interview complete · morale '+(delta>=0?'+':'')+delta)}
function mediaScreen(){return `<div class="stats"><div class="stat"><div class="label">MEDIA TRUST</div><b>${state.mediaTrust}%</b><small>Your public relationships</small></div><div class="stat"><div class="label">LOCKER ROOM</div><b>${state.morale}%</b><small>Morale affects match execution</small></div></div>${state.interviewPending?'<div class="panel"><div class="pad"><h2>The media are waiting.</h2><p class="subtitle">Your postgame press conference is ready.</p><button style="margin-top:16px" onclick="postInterview()">Attend press conference →</button></div></div>':''}${state.lastMatch?postgameCard(state.lastMatch):''}<div class="panel section-gap"><div class="panel-head"><h2>Press archive</h2><span class="label">${state.press.length} APPEARANCES</span></div>${state.press.length?state.press.map(p=>`<div class="news-item"><div class="news-icon">◌</div><div><small>${p.year} · ${p.type==='pre'?'Pregame':'Postgame'} · ${esc(p.coach)}</small><p>“${esc(p.quote)}”</p><small>Morale ${p.morale>=0?'+':''}${p.morale} · Media trust ${p.trust>=0?'+':''}${p.trust}</small></div></div>`).join(''):'<div class="empty">Interviews appear here after your first live game.</div>'}</div>`}
function coachScreen(){let c=state.coach;return `<div class="two"><div class="panel"><div class="panel-head"><h2>Head coach profile</h2><span class="tag green">CUSTOM COACH</span></div><div class="pad"><div class="coach-card"><div class="coach-portrait">♟</div><div><h2>${esc(c.name)}</h2><p class="subtitle">${c.style} · ${c.temperament}</p></div></div><div class="form-row"><label for="coach-name">Coach name</label><input id="coach-name" type="text" maxlength="40" value="${esc(c.name)}" onchange="setCoach('name',this.value)"></div>${[['style','Coaching philosophy',['Balanced','Run-first','Vertical offense']],['temperament','Leadership style',['Players coach','Disciplinarian','Tactician']],['offense','Default offensive formation',offenses],['defense','Default defensive personnel',defenses],['calling','Playcalling responsibility',['Manual','Head coach']]].map(([k,l,opts])=>`<div class="form-row"><label for="coach-${k}">${l}</label><select id="coach-${k}" onchange="setCoach('${k}',this.value)">${opts.map(o=>`<option ${c[k]===o?'selected':''}>${o}</option>`).join('')}</select></div>`).join('')}<p class="subtitle">Saved automatically. Formation defaults apply to your next game; change the current game’s formation from the sideline.</p></div></div><div><div class="panel"><div class="panel-head"><h2>Your coaching identity</h2></div><div class="pad"><h3>${c.style}</h3><p class="subtitle" style="line-height:1.8">${c.style==='Run-first'?'The head coach favors rushing on early downs, then uses play action to exploit the defense.':c.style==='Vertical offense'?'The head coach favors deep passes. More explosive potential comes with more incompletions and turnovers.':'A balanced mix of runs and passes, with situational decisions on fourth down.'}</p><div class="kv"><span>Leadership</span><b>${c.temperament}</b></div><p class="subtitle" style="line-height:1.8">${c.temperament==='Players coach'?'Players coach: starters lose 10% less energy per snap.':c.temperament==='Disciplinarian'?'Disciplinarian: small execution bonus when team morale is at least 70%.':'Tactician: small execution bonus when your offensive formation fits your chosen play.'}</p><div class="kv"><span>Calling</span><b>${c.calling}</b></div><p class="subtitle" style="line-height:1.8">Manual lets you pick each call. Head coach delegates situational play selection while you retain formations, tempo and substitutions.</p></div></div><div class="panel section-gap"><div class="panel-head"><h2>Branding & licensing</h2><button class="link" onclick="showLicensing()">Details ↗</button></div><div class="pad"><p class="license-note">Team logos identify the franchises. This independent fan simulation is not licensed, sponsored or endorsed by the NFL, its teams, ESPN or Sports Interactive. Real NFL roster identities are available; ratings and contracts are simulated.</p></div></div></div></div>`}
function setCoach(k,v){if(k==='name')v=v.trim().slice(0,40)||'Alex Morgan';state.coach[k]=v;render();toast('Head coach updated')}
function showLicensing(){modal(`<h2>Branding & credits</h2><p>This is an independent, <b>unlicensed fan simulation</b>. No official NFL license has been obtained. It is not affiliated with or endorsed by the NFL, its clubs, ESPN, Football Manager or Sports Interactive.</p><p>Team names and logos belong to their respective owners. Logo image source: ESPN’s team-logo CDN. Their display identifies the simulated franchises and does not grant permission for redistribution or commercial use.</p><p>Ratings, contracts, future events and the competition engine use original simulation models. The matchday interface is original, informed by FM26’s publicly described 2D overview, tactical controls and contextual advice.</p><p><a href="https://www.nfl.com/legal/terms/" target="_blank" rel="noopener">NFL terms and permission contact ↗</a><br><a href="https://www.footballmanager.com/fm26/features/where-storytelling-evolves-fm26s-match-day-experience" target="_blank" rel="noopener">FM26 matchday reference ↗</a></p><div class="modal-actions"><button onclick="closeModal()">Close</button></div>`)}
nextSeason=function(){let coach=state.coach,press=state.press,mediaTrust=state.mediaTrust,lastMatch=state.lastMatch;originalNextSeason();Object.assign(state,{coach,press,mediaTrust,lastMatch});render()};
startCareer=function(i){pauseAuto();if(animationTimer)clearTimeout(animationTimer);animating=false;originalStartCareer(i);ensureMatchState();render()};
chooseClub=function(){if(state.live){pauseAuto()}modal(`<h2>Your franchise. Your legacy.</h2><p>Start a fresh career with any team. This replaces the current browser save, including an unfinished match.</p><div class="club-grid">${clubs.map((c,i)=>`<button onclick="startCareer(${i})">${logo(i)}<b>${c[0]}</b><br>${c[2]}</button>`).join('')}</div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Keep current career</button></div>`)};
showHelp=function(){modal(`<h2>Your franchise. Every snap.</h2><p><b>Enter matchday</b> to play the next scheduled game. Answer the pregame interview, set your formation and play, then snap the ball.</p><p><b>Own the sideline.</b> Auto play runs consecutive snaps. Pause anytime to change formation, call plays or replace tired/injured starters. The head coach can choose calls for you.</p><p><b>Manage the moment.</b> Follow down and distance, field position, the clock and live stats. Fourth down is your decision: go for it, punt, or kick. Halftime pauses for your team talk.</p><p><b>Finish the job.</b> At the final whistle, commit the result to your season, review the postgame report, and answer the press. Interviews change morale and media trust.</p><p>Original 2D simulation with simplified NFL rules, fictional personnel and browser-local saving. See Branding & credits for sources and license status.</p><div class="modal-actions"><button class="secondary" onclick="showLicensing()">Branding & credits</button><button onclick="closeModal()">Let's play →</button></div>`)};
window.addEventListener('beforeunload',()=>{pauseAuto();save()});
ensureMatchState();render();
